      "content": "/**\n * The notification engine: watches the sessions-list snapshot for running\n * edges and the uiSession pending-interactions map for question/approval\n * edges, classifies each finished run as completed or failed from the chat\n * view nodes, and hands classified events to a dispatcher. The engine is\n * dependency-injected and DOM-free so the classification logic runs under\n * plain vitest; the browser wiring lives in `index.ts`.\n *\n * dsh 0.1.3-alpha.1 data model: the session snapshot still carries no chat\n * view or pending interaction — the chat view comes from\n * `uiConversation.binding(binding).target('chat')` and pending interactions\n * from the uiSession session-status source. The engine's session types now come\n * from the api-session-controller client (dsh-client-runtime was dissolved);\n * `AssistantBlock`/`TurnErrorNode` live with the ui-conversation records.\n */\nimport type { SessionId } from '@deepseek-ai/dsh-client-connection/client'\nimport type {\n  SessionListState, SessionSnapshot,\n} from '@deepseek-ai/dsh-api-session-controller/client'\n// dsh 0.1.3: the runtime package is gone; the chat-view node payload types\n// (assistant text blocks and turn-error records) live with the conversation\n// records in ui-conversation (re-exported by ui-chat's snapshot contract).\nimport type {\n  AssistantBlock, TurnErrorNode,\n} from '@deepseek-ai/dsh-client-ui-conversation/client'\nimport { NOTIFICATION_TAG_PREFIX } from './browser-notify.ts'\nimport type { NotificationMode, NotificationSettings, NotificationType, SoundId } from '../settings.ts'\n\n/** One selectable notification kind (re-export for the settings rows). */\nexport type { NotificationType } from '../settings.ts'\n\n/** Minimal structural view of the alpha chat target snapshot (ui-chat ChatSnapshot). */\nexport interface ChatViewNode {\n  kind: string\n  data: unknown\n}\n\n/** Minimal structural view of the chat node store. */\nexport interface ChatNodeStoreLike {\n  values(): IterableIterator<ChatViewNode>\n}\n\n/** Minimal structural view of the chat snapshot the engine classifies on. */\nexport interface ChatSnapshotLike {\n  nodes: ChatNodeStoreLike\n}\n\n/** One pending interaction's notification facts (from uiSession). */\nexport interface PendingFacts {\n  /** Interaction identity; a replacement interaction carries a new key. */\n  key: string\n  /** Plugin notification kind: question covers 'question'/'plan-review'. */\n  kind: 'question' | 'approval'\n  /** Interaction detail text (question text / tool name). */\n  detail: string\n}\n\n/** Per-session facts the engine reads from the session and chat snapshots. */\nexport interface SessionDetail {\n  /** Max seq of materialized turn-error nodes (unretried failures only). */\n  maxTurnErrorSeq: number\n  /** Most recent failure message, when one is visible. */\n  failureMessage: string | null\n  /** Host agent-error text, null when none. */\n  lastAgentError: string | null\n  /** Text of the last assistant message (the final completion text); '' when none. */\n  finalText: string\n  /** Text of the latest human user message (the run's subject), when known. */\n  lastUserText?: string\n}\n\n/** One classified notification event. */\nexport interface NotificationEvent {\n  kind: NotificationType\n  sessionId: SessionId\n  /** Human display title of the session. */\n  title: string\n  /** Kind-specific detail (error message, question text, tool name). */\n  detail: string\n}\n\n/** Engine dependencies (injected by the browser wiring; stubbed in tests). */\nexport interface NotificationEnginePorts {\n  /** Read one session's detail snapshot; undefined when unavailable. */\n  detailOf: (sessionId: SessionId) => SessionDetail | undefined\n  /**\n   * Materialize the detail inputs before the settle read (open a session the\n   * UI never opened so its chat view can assemble the final assistant text).\n   * Optional and best-effort: a failure must not lose the classification.\n   */\n  ensureDetail?: (sessionId: SessionId) => Promise<void>\n  /** Human display title of one session. */\n  titleOf: (sessionId: SessionId) => string\n  /** Wait for trailing wire frames after a running edge (settle window). */\n  settle: () => Promise<void>\n  /** Whether one session is a subagent (never the main session). */\n  isSubagent: (sessionId: SessionId) => boolean\n  /** Whether one session still has a running descendant (recursive). */\n  hasRunningDescendants: (sessionId: SessionId) => boolean\n  /**\n   * Whether the host holds work that starts another turn by itself (a queued\n   * follow-up or an owed goal round); the running bit is false there, so a\n   * completion notice would announce an end that has not happened.\n   */\n  hasUnfinishedWork?: (sessionId: SessionId) => boolean\n  /** Deliver one classified event. */\n  emit: (event: NotificationEvent) => void\n}\n\n/** Baseline captured when a run starts. */\ninterface RunState {\n  baselineErrorSeq: number\n  baselineAgentError: string | null\n}\n\n/**\n * Classifies session lifecycle edges into notification events. Running\n * true→false transitions arm a classification (completed vs failed) after the\n * settle window; a pending-interaction arrival raises the question/permission\n * kinds (observed through the uiSession pending map). A session that was\n * already idle when observation started raises nothing.\n */\nexport class NotificationEngine {\n  private readonly prevRunning = new Map<SessionId, boolean>()\n  private readonly runs = new Map<SessionId, RunState>()\n  private readonly settling = new Set<SessionId>()\n  private readonly pendingKeys = new Map<SessionId, string>()\n  /** Completions held back until every descendant subagent has finished. */\n  private readonly heldCompletions = new Map<SessionId, string>()\n  /** Notification scope. Defaults to the durable default; wiring syncs it. */\n  private mode: NotificationMode = 'main-wait'\n\n  /** @param ports - injected readers and sink. */\n  constructor(private readonly ports: NotificationEnginePorts) {}\n\n  /** Update the notification scope (which sessions alert, subagent wait). */\n  setNotificationMode(mode: NotificationMode): void {\n    const previous = this.mode\n    this.mode = mode\n    // Silencing subagents forgets their tracking so a stale running edge can\n    // never fire for one after the switch.\n    if (mode !== 'all') this.forgetSubagents()\n    // Leaving the waiting mode releases anything already held.\n    if (previous === 'main-wait' && mode !== 'main-wait') this.releaseHeld()\n  }\n\n  /** Emit every held completion whose descendants have all settled. */\n  private releaseHeld(): void {\n    for (const [id, detail] of [...this.heldCompletions]) {\n      // Work that will continue the session has no end to announce yet.\n      if (this.ports.hasUnfinishedWork?.(id) === true) {\n        this.heldCompletions.delete(id)\n        continue\n      }\n      if (this.waitsFor(id)) continue\n      this.heldCompletions.delete(id)\n      this.ports.emit({ kind: 'completed', sessionId: id, title: this.ports.titleOf(id), detail })\n    }\n  }\n\n  /** Whether one session should stay silent (subagents under a main-only mode). */\n  private silenced(id: SessionId): boolean {\n    return this.mode !== 'all' && this.ports.isSubagent(id)\n  }\n\n  /** Whether one completion must wait for its still-running descendants. */\n  private waitsFor(id: SessionId): boolean {\n    return this.mode === 'main-wait' && this.ports.hasRunningDescendants(id)\n  }\n\n  /** Drop tracking state for every subagent session (subagents were silenced). */\n  private forgetSubagents(): void {\n    for (const id of new Set([...this.prevRunning.keys(), ...this.runs.keys(), ...this.pendingKeys.keys()])) {\n      if (!this.ports.isSubagent(id)) continue\n      this.prevRunning.delete(id)\n      this.runs.delete(id)\n      this.pendingKeys.delete(id)\n    }\n  }\n\n  /**\n   * Process one sessions-list snapshot (called on every list change).\n   * @param sessions - the latest list snapshot.\n   */\n  observe(sessions: SessionListState): void {\n    const seen = new Set<SessionId>()\n    for (const summary of Object.values(sessions.byId)) {\n      const id = summary.id\n      seen.add(id)\n      if (this.silenced(id)) {\n        // Never track a silenced subagent; drop any state left from when the\n        // filter was off so no stale edge fires.\n        this.prevRunning.delete(id)\n        this.runs.delete(id)\n        this.pendingKeys.delete(id)\n        continue\n      }\n      const prevRunning = this.prevRunning.get(id) ?? false\n      if (prevRunning && !summary.running) {\n        void this.settleRun(id)\n      } else if (!prevRunning && summary.running) {\n        this.armRun(id)\n      }\n      this.prevRunning.set(id, summary.running)\n    }\n    for (const id of this.prevRunning.keys()) {\n      if (!seen.has(id)) {\n        this.prevRunning.delete(id)\n        this.runs.delete(id)\n        this.pendingKeys.delete(id)\n        this.heldCompletions.delete(id)\n      }\n    }\n    // A descendant may have just settled: release any completion waiting on it.\n    this.releaseHeld()\n  }\n\n  /**\n   * Establish the baseline before live observation: record every session's\n   * current running bit and arm runs already in progress, but raise nothing —\n   * idle sessions that predate the plugin raise no notification.\n   * @param sessions - the first list snapshot.\n   */\n  seed(sessions: SessionListState): void {\n    for (const summary of Object.values(sessions.byId)) {\n      const id = summary.id\n      if (this.silenced(id)) continue\n      this.prevRunning.set(id, summary.running)\n      if (summary.running) this.armRun(id)\n    }\n  }\n\n  /**\n   * Process one uiSession pending-interactions snapshot. A session entering\n   * the map (or replacing its interaction — a new key, or a kind switch)\n   * raises the question/permission kind; leaving the map raises nothing.\n   * @param pending - current effective pending interaction per session.\n   */\n  observePending(pending: ReadonlyMap<SessionId, PendingFacts>): void {\n    for (const [id, facts] of pending) {\n      if (this.silenced(id)) {\n        this.pendingKeys.delete(id)\n        continue\n      }\n      const prevKey = this.pendingKeys.get(id)\n      if (prevKey === undefined || prevKey !== facts.key) {\n        this.raise(facts.kind, id, facts.detail)\n      }\n      this.pendingKeys.set(id, facts.key)\n    }\n    for (const id of this.pendingKeys.keys()) {\n      if (!pending.has(id)) this.pendingKeys.delete(id)\n    }\n  }\n\n  /** Capture the pre-run failure baseline when a run starts. */\n  private armRun(id: SessionId): void {\n    // A new run supersedes any completion still waiting on descendants.\n    this.heldCompletions.delete(id)\n    const detail = this.ports.detailOf(id)\n    this.runs.set(id, {\n      baselineErrorSeq: detail?.maxTurnErrorSeq ?? 0,\n      baselineAgentError: detail?.lastAgentError ?? null,\n    })\n  }\n\n  /** Classify a finished run after the settle window (completed vs failed). */\n  private async settleRun(id: SessionId): Promise<void> {\n    const run = this.runs.get(id)\n    if (run === undefined || this.settling.has(id)) return\n    this.runs.delete(id)\n    this.settling.add(id)\n    try {\n      await this.ports.settle()\n      // A newer run armed while settling will classify itself; skip the stale one.\n      if (this.runs.has(id)) return\n      // The filter may have changed while settling (e.g. main-only re-enabled):\n      // never emit for a session that is now silenced.\n      if (this.silenced(id)) {\n        this.prevRunning.delete(id)\n        return\n      }\n      // A session the user never opened has no loaded history, so its chat\n      // view holds no nodes yet; materialize it best-effort before reading.\n      try {\n        await this.ports.ensureDetail?.(id)\n      } catch {\n        // Best effort only: classify from whatever snapshot reads exist.\n      }\n      const detail = this.ports.detailOf(id)\n      const failed = detail !== undefined && (\n        detail.maxTurnErrorSeq > run.baselineErrorSeq ||\n        (detail.lastAgentError !== null && detail.lastAgentError !== run.baselineAgentError)\n      )\n      const message = failed\n        ? (detail?.failureMessage ?? detail?.lastAgentError ?? '')\n        : (detail?.finalText ?? '')\n      if (failed) {\n        // A failure is actionable now: never hold it behind subagents.\n        this.heldCompletions.delete(id)\n        this.ports.emit({ kind: 'failed', sessionId: id, title: this.label(id, detail), detail: message })\n        return\n      }\n      // The host resumes the session by itself: this idle edge is a pause, and\n      // the continuation's own end classifies instead. Never hold the notice —\n      // a superseded run has nothing left to announce.\n      if (this.ports.hasUnfinishedWork?.(id) === true) return\n      // Hold the completion while descendants still run: the session only\n      // paused between subagent waves, so alert when the whole fan-out ends.\n      if (this.waitsFor(id)) {\n        this.heldCompletions.set(id, message)\n        return\n      }\n      this.ports.emit({ kind: 'completed', sessionId: id, title: this.label(id, detail), detail: message })\n    } finally {\n      this.settling.delete(id)\n    }\n  }\n\n  /** The run's latest user message, else the first-prompt session title. */\n  private label(id: SessionId, detail: SessionDetail | undefined): string {\n    const text = truncateTitle(detail?.lastUserText ?? '')\n    return text.length > 0 ? text : this.ports.titleOf(id)\n  }\n\n  /** Raise the question/permission kind on a pending-interaction arrival. */\n  private raise(kind: PendingFacts['kind'], id: SessionId, detail: string): void {\n    this.ports.emit({\n      // The plugin's four kinds fold the alpha 'approval' interaction into\n      // the 'permission' kind (and 'question'/'plan-review' into 'question').\n      kind: kind === 'approval' ? 'permission' : 'question',\n      sessionId: id,\n      title: this.ports.titleOf(id),\n      detail,\n    })\n  }\n}\n\n/**\n * Project one session's lifecycle + chat snapshots into the engine's\n * {@link SessionDetail}. The final completion text is the joined text of the\n * last assistant step (the chat view's `assistant-step` node) that carries\n * any; the run's subject is the latest human user message, so a notice names\n * the request it answered instead of the first-prompt session title. Failure\n * classification reads the chat view's turn-error nodes plus the session's\n * host agent-error. An absent chat target (session not opened) yields no\n * turn-error, final-text, or user-message facts, never a throw.\n * @param session - the session lifecycle snapshot (session-controller).\n * @param chat - the session's chat view snapshot, when one is materialized.\n * @returns the derived detail.\n */\nexport function sessionDetailOf(\n  session: SessionSnapshot,\n  chat: ChatSnapshotLike | undefined,\n): SessionDetail {\n  let maxTurnErrorSeq = 0\n  let failureMessage: string | null = null\n  let finalText = ''\n  let lastUserText = ''\n  if (chat !== undefined) {\n    for (const node of chat.nodes.values()) {\n      if (node.kind === 'turn-error') {\n        const data = node.data as TurnErrorNode\n        if (data.seq > maxTurnErrorSeq) {\n          maxTurnErrorSeq = data.seq\n          failureMessage = data.message\n        }\n      } else if (node.kind === 'assistant-step') {\n        const data = node.data as { blocks: readonly AssistantBlock[] }\n        const text = data.blocks\n          .filter((block): block is Extract<AssistantBlock, { kind: 'text' }> => block.kind === 'text')\n          .map(block => block.text)\n          .join('')\n        if (text.length > 0) finalText = text\n      } else if (node.kind === 'user') {\n        // Human messages only: goal rounds and other host prompts share the role.\n        const data = node.data as { content: readonly { type: string, text?: string }[], source?: { kind?: string } }\n        if (data.source?.kind === 'user') {\n          lastUserText = data.content\n            .filter(block => block.type === 'text' && block.text !== undefined)\n            .map(block => block.text)\n            .join('')\n        }\n      }\n    }\n  }\n  return {\n    maxTurnErrorSeq,\n    failureMessage,\n    lastAgentError: session.lastAgentError,\n    finalText,\n    lastUserText,\n  }\n}\n\n/** Cap the notification subject (a user message can be a whole paragraph). */\nexport function truncateTitle(text: string, max = 60): string {\n  const collapsed = text.replace(/\\s+/g, ' ').trim()\n  if (collapsed.length <= max) return collapsed\n  return `${collapsed.slice(0, max - 1)}…`\n}\n\n/** Cap the detail text shown in a notification. */\nexport function truncateDetail(text: string, max = 160): string {\n  if (text.length <= max) return text\n  return `${text.slice(0, max - 1)}…`\n}\n\n/** Dispatcher dependencies (injected by the browser wiring; stubbed in tests). */\nexport interface NotificationDispatcherDeps {\n  /** Read the current durable preferences at dispatch time. */\n  settings: () => NotificationSettings\n  /** Bound namespace translate. */\n  t: (key: string) => string\n  /**\n   * Play one sound effect; `custom` carries the data URL resolved from\n   * {@link customSoundOf}.\n   */\n  playSound: (sound: SoundId, customUrl?: string) => void\n  /** Read one kind's custom sound data URL (undefined = use the built-in). */\n  customSoundOf: (kind: NotificationType) => string | undefined\n  /** Show one system notification; returns whether it was shown. */\n  /**\n   * Show one system notification under the event kind's collapse tag; the\n   * session id lets the click action navigate back to the event's session.\n   */\n  showBrowser: (title: string, body: string, tag: string, sessionId: SessionId) => boolean\n  /** Whether one session is the one currently shown in the main view. */\n  isCurrent: (sessionId: SessionId) => boolean\n  /** Whether the document is hidden (background tab, minimized, or occluded). */\n  isHidden: () => boolean\n  /**\n   * Whether the document has focus; false while another application is in\n   * front. Optional — an absent reader counts as focused, the quiet side.\n   */\n  hasFocus?: () => boolean\n}\n\n/**\n * Applies the durable preferences to one classified event. The session you\n * are reading stays quiet by default; `currentNotificationMode` widens that\n * (`unfocused` also alerts once another application is in front, `always`\n * alerts regardless). Every other session alerts whenever you are away from\n * it: the kind's effective sound plays when sound is enabled, and a system\n * notification shows when browser notifications are enabled.\n */\nexport class NotificationDispatcher {\n  /** @param deps - injected readers and sinks. */\n  constructor(private readonly deps: NotificationDispatcherDeps) {}\n\n  /**\n   * Dispatch one event.\n   * @param event - the classified event.\n   */\n  dispatch(event: NotificationEvent): void {\n    const settings = this.deps.settings()\n    const type = settings.types[event.kind]\n    if (!type.enabled) return\n    const isCurrent = this.deps.isCurrent(event.sessionId)\n    const mode = settings.currentNotificationMode\n    // \"Away\" from the session you are reading: a backgrounded window counts\n    // for every mode, another application in front only for 'unfocused', and\n    // 'always' is never quiet. Focus is read only when the mode needs it.\n    const away = this.deps.isHidden() || (mode === 'unfocused' && this.deps.hasFocus?.() === false)\n    if (isCurrent && !away && mode !== 'always') return\n\n    const title = this.deps.t(`notify.${event.kind}.title`)\n    const template = this.deps.t(`notify.${event.kind}.body`)\n    const detail = truncateDetail(event.detail)\n    const base = template.replaceAll('{title}', event.title)\n    // A completed run's detail is the final assistant text — show it on its\n    // own line so long-form content reads naturally; the other kinds embed\n    // the detail inline in their templates.\n    const body = event.kind === 'completed'\n      ? (detail.length > 0 ? `${base}\\n${detail}` : base)\n      : base.replaceAll('{detail}', detail)\n    if (settings.soundEnabled) {\n      // The custom audio plays only when the kind's picker selects 自定义;\n      // otherwise the selected built-in plays (a dormant custom file is inert).\n      if (type.sound === 'custom') {\n        const customUrl = this.deps.customSoundOf(event.kind)\n        if (customUrl !== undefined) this.deps.playSound('custom', customUrl)\n      } else if (type.sound !== 'none') {\n        this.deps.playSound(type.sound)\n      }\n    }\n    if (!settings.browserEnabled) return\n    this.deps.showBrowser(title, body, `${NOTIFICATION_TAG_PREFIX}:${event.kind}`, event.sessionId)\n  }\n}\n"
    },
    {
      "path": "src/client/index.ts",
      "content": "/**\n * Notification plugin, browser half: the Notifications settings section and\n * the event-driven notification engine. The engine watches the sessions list\n * for running and pending-interaction edges, classifies finished runs as\n * completed or failed from the session's conversation snapshot, and hands\n * events to a dispatcher that plays the kind's sound and shows a system\n * notification when browser notifications are enabled.\n *\n * The settings section follows the official row pattern (ui-theme): the\n * store declared at register is owned by the slot renderer, which hands its\n * bound actions to the inject factory; the apply world never creates a\n * second instance. The scope is the source of truth for reads (dispatcher,\n * engine) and writes; the bound actions mirror scope snapshots into the\n * renderer's store.\n *\n * Preferences are browser-local (localStorage, `createLocalSettingsScope`):\n * the plugin owns its namespace end to end and needs no host-side settings\n * exposure, so it runs against a pristine harness without touching\n * `packages/host/apiproxy` or any other host package.\n */\nimport type { BoundActions } from '@deepseek-ai/dsh-client-ui-slots'\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport type { SessionId } from '@deepseek-ai/dsh-client-connection/client'\n// Type-only: the SlotRegistry service merge (ctx.slots) — dsh 0.1.3 merged it\n// through ui-renderer's client face (dsh-client-runtime was dissolved).\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\n// Type-only: the settings surface's slot-name augmentation, which types the\n// `settings.section` seat this plugin registers (a side effect of importing\n// the face is the ctx.settingsScope Context merge, which the plugin no\n// longer uses — preferences are browser-local).\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\n// Type-only: the locale plugin's Context merge (ctx.locale).\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\n// Type-only: the sessions service (ctx.sessions) and the chat/pending\n// surfaces the engine reads (ctx.uiConversation / ctx.uiSession).\nimport type {} from '@deepseek-ai/dsh-api-session-controller/client'\nimport type { SessionSnapshot } from '@deepseek-ai/dsh-api-session-controller/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-conversation/client'\nimport type {\n  SessionStatusSnapshot,\n} from '@deepseek-ai/dsh-client-ui-session/client'\n// Type-only: the workspace navigation merge (ctx.uiWorkspace). Injected\n// optionally so a composition without it keeps the plugin running.\nimport type {} from '@deepseek-ai/dsh-client-ui-workspace/client'\nimport type { CurrentNotificationMode, NotificationMode, NotificationSettings, NotificationType, SoundId } from '../settings.ts'\nimport { DEFAULT_NOTIFICATION_SETTINGS } from '../settings.ts'\nimport { createLocalSettingsScope } from './local-settings.ts'\nimport { createTabCoordinator } from './tab-coordinator.ts'\nimport { SoundPlayer } from './sounds.ts'\nimport {\n  browserPermission, requestBrowserPermission, showBrowserNotification, NOTIFICATION_TAG_PREFIX,\n} from './browser-notify.ts'\nimport { MAX_CUSTOM_AUDIO_BYTES, readCustomSound, readFileAsDataUrl, writeCustomSound } from './custom-audio.ts'\nimport {\n  NotificationDispatcher, NotificationEngine, sessionDetailOf,\n  type ChatSnapshotLike, type PendingFacts,\n} from './notification-service.ts'\nimport { createNotificationsStore } from './settings-store.ts'\nimport {\n  NotificationsSection, type NotificationsSectionInjected,\n} from './NotificationsSection.tsx'\nimport { en, zh, type NotificationsKey } from './locales.ts'\n\ndeclare module '@deepseek-ai/dsh-client-ui-slots' {\n  interface LocaleNamespaceMap {\n    /** The Notifications settings section's copy. */\n    'notifications': NotificationsKey\n  }\n}\n\ndeclare module '@deepseek-ai/dsh-api-session-controller/client' {\n  interface SessionReferenceSourceMap {\n    /** Reference held while one notification classification reads a session. */\n    sessionNotification: unknown\n  }\n}\n\n/** Dictionary namespace owned by this plugin. */\nconst NS = 'notifications'\n\n/** How long a finished run waits for trailing wire frames before classification. */\nconst SETTLE_MS = 250\n\n/** Required services: the slot registry, dictionaries, the session list, the\n *  alpha chat view (uiConversation), and the pending-interaction map\n *  (uiSession). */\nexport const inject = ['slots', 'locale', 'sessions', 'uiConversation', 'uiSession', 'uiWorkspace']\n\n/**\n * Client plugin body: bind the browser-local preferences scope, register the\n * Notifications section, and watch the sessions list for notification events.\n * @param ctx - client root context.\n */\nexport function apply(ctx: ClientContext): void {\n  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'dsh-session-notification: dictionaries')\n\n  const scope = createLocalSettingsScope()\n  const store = createNotificationsStore()\n  let bound: BoundActions<typeof store> | undefined\n\n  const currentSettings = (): NotificationSettings => {\n    const snapshot = scope.getSnapshot()\n    return snapshot.status === 'ready' && snapshot.value !== undefined\n      ? snapshot.value\n      : DEFAULT_NOTIFICATION_SETTINGS\n  }\n\n  // Scope → renderer store mirror. The renderer binds its own store instance\n  // and hands it to the inject factory; until the section mounts, adopt is a\n  // no-op (the inject factory performs the first sync on mount). The engine's\n  // main-only filter is synced from the same subscription below, where the\n  // engine already exists.\n  ctx.effect(() => scope.subscribe(() => { bound?.adopt(scope.getSnapshot()) }), 'dsh-session-notification: scope adoption')\n\n  const player = new SoundPlayer(() => currentSettings().volume)\n  // Release the shared AudioContext (and any preview still holding it) when\n  // the plugin unloads; a live context keeps a system audio stream open.\n  ctx.effect(() => () => player.dispose(), 'dsh-session-notification: sound player')\n\n  // Cross-tab arbiter: one open tab wins each event, so N tabs do not ring N\n  // times; a visible tab takes the event ahead of a background one.\n  const coordinator = createTabCoordinator()\n  ctx.effect(() => () => coordinator.dispose(), 'dsh-session-notification: tab coordinator')\n  const t = ctx.locale.bind(NS)\n  const translate = (key: string): string => t(key as NotificationsKey)\n  /** Play the effective sound: a custom audio when one is supplied, else the built-in. */\n  const playEffective = (sound: SoundId, customUrl?: string): void => {\n    if (sound === 'custom' && customUrl !== undefined) player.playCustom(customUrl)\n    else player.play(sound)\n  }\n\n  const dispatcher = new NotificationDispatcher({\n    settings: currentSettings,\n    t: translate,\n    playSound: (sound, customUrl) => { playEffective(sound, customUrl) },\n    customSoundOf: (kind) => readCustomSound(kind),\n    showBrowser: (title, body, tag, sessionId) => showBrowserNotification(title, body, tag, () => {\n      try {\n        ctx.uiWorkspace.openSession(sessionId)\n      } catch (error) {\n        console.warn('[dsh-session-notification] could not open the notification session', sessionId, error)\n      }\n    }),\n    // dsh 0.1.7 dropped the list's `current` selection; the main view owns\n    // selection through its reference source, so a session is \"the one being\n    // read\" while the main-view reference retains it.\n    isCurrent: (id) => (ctx.sessions.retainInfo(id).getSnapshot().retainedBy.mainView ?? 0) > 0,\n    isHidden: () => (typeof document === 'undefined' ? false : document.visibilityState === 'hidden'),\n    // `visibilityState` stays visible while another app is in front and this\n    // window is still on screen; focus is the signal for that case.\n    hasFocus: () => typeof document === 'undefined' || document.hasFocus(),\n  })\n\n  const engine = new NotificationEngine({\n    detailOf: (id: SessionId) => {\n      const binding = ctx.sessions.binding(id)\n      if (binding === undefined) return undefined\n      // The session snapshot carries no chat view: the conversation nodes\n      // live in the uiConversation chat target, materialized only for opened\n      // sessions. Absent it, classification still has lastAgentError.\n      // (The chat target key and the session snapshot shape are surfaced\n      // through their owning packages' type merges; the structural casts keep\n      // this plugin independent of those augmentation orders.) A generation\n      // that ends between the running edge and this read makes the binding\n      // calls throw in 0.1.7, so a failed read degrades to \"no detail\".\n      try {\n        const conversation = ctx.uiConversation.binding(binding) as unknown as {\n          activate(target: string): void\n          target(key: string): { getSnapshot(): unknown }\n        }\n        // Reading a target source does not activate it in 0.1.7+; without\n        // activation the chat nodes this classification needs stay absent for\n        // every session the shell has not selected.\n        conversation.activate('chat')\n        const chat = conversation.target('chat').getSnapshot() as ChatSnapshotLike | undefined\n        const session = binding.session.getSnapshot() as unknown as SessionSnapshot\n        return sessionDetailOf(session, chat)\n      } catch {\n        return undefined\n      }\n    },\n    // Open a session the UI never opened so its chat view can assemble the\n    // final assistant text; skipped when no alert could use it.\n    ensureDetail: async (id) => {\n      const settings = currentSettings()\n      if (!settings.browserEnabled && !settings.soundEnabled) return\n      if (!Object.values(settings.types).some(type => type.enabled)) return\n      try {\n        await ctx.sessions.using(id, { source: 'sessionNotification' }, async () => {})\n      } catch (error) {\n        console.warn('[dsh-session-notification] could not load the notification session', id, error)\n      }\n    },\n    titleOf: (id: SessionId) => ctx.sessions.list.getSnapshot().byId[id]?.displayTitle ?? id,\n    // The host will resume this session by itself: a queued follow-up is\n    // claimed as the next turn, and a goal round is queued once the driver sees\n    // idle. The running bit is false in both gaps, so that idle edge is a\n    // pause, not an end. Read from the list snapshot to cover unopened sessions.\n    hasUnfinishedWork: (id) => {\n      // Structural: the `inbox` and `goal` projection wire values, no host imports.\n      const values = ctx.sessions.list.getSnapshot().projectionsBySession[id]?.values as {\n        inbox?: { 'next-turn'?: readonly unknown[], 'next-step'?: readonly unknown[] }\n        goal?: { goal: { phase: string, maxGoalRounds: number }, roundsStarted: number } | null\n      } | undefined\n      const inbox = values?.inbox\n      if ((inbox?.['next-turn']?.length ?? 0) > 0 || (inbox?.['next-step']?.length ?? 0) > 0) return true\n      const goal = values?.goal\n      // A goal that reached its round cap is blocked by the driver, not continued.\n      return goal?.goal.phase === 'active' && goal.roundsStarted < goal.goal.maxGoalRounds\n    },\n    settle: () => new Promise(resolve => setTimeout(resolve, SETTLE_MS)),\n    // Subagents live in the same sessions list, flagged by their summary\n    // origin; the main-only filter silences them.\n    isSubagent: (id: SessionId) =>\n      ctx.sessions.list.getSnapshot().byId[id]?.origin === 'subagent',\n    // Walk the parentId chain so a nested subagent keeps its root's completion\n    // held too (a subagent may itself fan out).\n    hasRunningDescendants: (id: SessionId) => {\n      const byId = ctx.sessions.list.getSnapshot().byId\n      const seen = new Set<SessionId>([id])\n      const queue: SessionId[] = [id]\n      while (queue.length > 0) {\n        const parent = queue.shift() as SessionId\n        for (const summary of Object.values(byId)) {\n          if (summary.parentId !== parent || seen.has(summary.id)) continue\n          seen.add(summary.id)\n          if (summary.running) return true\n          queue.push(summary.id)\n        }\n      }\n      return false\n    },\n    emit: (event) => {\n      // One tab wins the event (a visible tab ahead of a background one); the\n      // others stay silent for it. Without BroadcastChannel every tab claims\n      // its own event, i.e. the pre-coordination behavior.\n      void coordinator.claim(`${event.sessionId}:${event.kind}`).then((owned) => {\n        if (owned) dispatcher.dispatch(event)\n      })\n    },\n  })\n  // Keep the engine's notification scope in lockstep with the preference.\n  engine.setNotificationMode(currentSettings().notificationMode)\n  // Re-sync on every scope change (including other tabs).\n  ctx.effect(() => scope.subscribe(() => {\n    engine.setNotificationMode(currentSettings().notificationMode)\n  }), 'dsh-session-notification: mode sync')\n  ctx.effect(() => {\n    const unsubscribe = ctx.sessions.list.subscribe(() => engine.observe(ctx.sessions.list.getSnapshot()))\n    // Establish the baseline so pre-existing state raises nothing.\n    engine.seed(ctx.sessions.list.getSnapshot())\n    return unsubscribe\n  }, 'dsh-session-notification: session watch')\n\n  // dsh 0.1.7 unified the pending-interaction map into the uiSession session\n  // status source (running + pendingInteraction + completionUnread per\n  // session): observe its pendingInteraction values for question/approval\n  // edges.\n  const pendingFactsOf = (statuses: SessionStatusSnapshot): Map<SessionId, PendingFacts> => {\n    const out = new Map<SessionId, PendingFacts>()\n    for (const [id, status] of statuses) {\n      const interaction = status.pendingInteraction\n      if (interaction === undefined) continue\n      const kind = interaction.kind === 'approval'\n        ? 'approval' as const\n        : (interaction.kind === 'question' || interaction.kind === 'plan-review')\n          ? 'question' as const\n          : undefined\n      if (kind === undefined) continue\n      const questions = (interaction as unknown as { questions?: readonly { question?: string }[] }).questions\n      const tool = (interaction as unknown as { toolName?: string }).toolName\n      const detail = questions?.[0]?.question ?? tool ?? ''\n      out.set(id, { key: interaction.key, kind, detail })\n    }\n    return out\n  }\n  ctx.effect(() => ctx.uiSession.sessionStatus.subscribe(() => {\n    engine.observePending(pendingFactsOf(ctx.uiSession.sessionStatus.getSnapshot()))\n  }), 'dsh-session-notification: pending watch')\n\n  /** Persist one top-level preference through the scope, mirroring optimistically. */\n  const persist = (field: 'browserEnabled' | 'currentNotificationMode' | 'notificationMode' | 'soundEnabled' | 'volume', value: unknown): void => {\n    if (field === 'browserEnabled') bound?.setBrowserEnabled(value as boolean)\n    else if (field === 'currentNotificationMode') bound?.setCurrentNotificationMode(value as CurrentNotificationMode)\n    else if (field === 'notificationMode') bound?.setNotificationMode(value as NotificationMode)\n    else if (field === 'soundEnabled') bound?.setSoundEnabled(value as boolean)\n    else bound?.setVolume(value as number)\n    void scope.set(field, value)\n  }\n\n  /** Persist one per-kind preference (the whole `types` section is one field). */\n  const persistType = (kind: NotificationType, patch: Partial<{ enabled: boolean; sound: SoundId }>): void => {\n    const next = { ...currentSettings().types[kind], ...patch }\n    bound?.setType(kind, patch)\n    void scope.set('types', { ...currentSettings().types, [kind]: next })\n  }\n\n  const injected = (actions: BoundActions<typeof store>): NotificationsSectionInjected => {\n    bound = actions\n    // First sync on mount: push the accepted scope value into the renderer's store.\n    bound.adopt(scope.getSnapshot())\n    return {\n      setBrowserEnabled: async (enabled) => {\n        if (enabled) {\n          let permission = browserPermission()\n          if (permission === 'default') {\n            permission = await requestBrowserPermission()\n            bound?.setPermission(permission)\n          }\n          if (permission !== 'granted') return\n        }\n        persist('browserEnabled', enabled)\n      },\n      setCurrentNotificationMode: (mode) => { persist('currentNotificationMode', mode) },\n      setNotificationMode: (mode) => { persist('notificationMode', mode) },\n      setSoundEnabled: (enabled) => { persist('soundEnabled', enabled) },\n      setVolume: (volume) => { persist('volume', Math.min(1, Math.max(0, volume))) },\n      setType: (kind, patch) => { persistType(kind, patch) },\n      testSound: (sound, customUrl) => { playEffective(sound, customUrl) },\n      requestPermission: async () => {\n        bound?.setPermission(await requestBrowserPermission())\n      },\n      testBrowserNotification: () => {\n        showBrowserNotification(t('test.notification.title'), t('test.notification.body'), `${NOTIFICATION_TAG_PREFIX}:test`)\n      },\n      uploadCustomSound: async (kind, file) => {\n        if (file.size > MAX_CUSTOM_AUDIO_BYTES) return\n        const dataUrl = await readFileAsDataUrl(file)\n        writeCustomSound(kind, dataUrl)\n        bound?.setCustomSound(kind, dataUrl)\n        // Uploading from the 自定义 picker selection persists the selection too.\n        persistType(kind, { sound: 'custom' })\n      },\n    }\n  }\n\n  ctx.slots.inject('settings.section', () => ctx.slots.register({\n    name: 'settings.section',\n    id: 'notifications',\n    order: 40,\n    label: () => t('nav'),\n    store,\n    locale: NS,\n    inject: injected,\n  }, NotificationsSection))\n}\n"
    },
    {
      "path": "src/client/local-settings.ts",
      "content": "/**\n * Browser-local preferences scope for the notification plugin.\n *\n * The notification preferences are owned end to end by this plugin and\n * persist in the browser (localStorage), so the plugin works against a\n * pristine harness — no host-side settings-namespace exposure, no change to\n * `packages/host/apiproxy` or any other host package. dsh 0.1.7-alpha.1\n * renamed the client settings contract to `ConfigForm` (schema-derived plugin\n * config forms over the profile patch); this scope implements that official\n * contract over localStorage, so nothing else in the plugin depends on the\n * host settings transport. Reads resolve through the same\n * `resolveNotificationSettings` decoder the host document path used, so\n * hand-edited or malformed storage degrades to the defaults.\n */\n// The official client settings-form contract (0.1.7 renamed SettingsScope to\n// ConfigForm; the write methods now settle with a boolean).\nimport type { ConfigForm, ConfigFormSnapshot } from '@deepseek-ai/dsh-client-ui-settings/client'\n// The mutation op shape the contract carries (dsh-settings owns the wire view).\nimport type { SettingsPathOpView } from '@deepseek-ai/dsh-settings/types'\nimport {\n  DEFAULT_NOTIFICATION_SETTINGS, NOTIFICATIONS_NS, resolveNotificationSettings,\n  type NotificationSettings,\n} from '../settings.ts'\n\n/** Re-exported for the section store (the official 0.1.7 form snapshot). */\nexport type { ConfigFormSnapshot } from '@deepseek-ai/dsh-client-ui-settings/client'\n\n/** localStorage key holding the whole preferences section. */\nexport const LOCAL_STORAGE_KEY = `${NOTIFICATIONS_NS}:preferences`\n\n/** Read the browser storage when present (absent in Node/SSR). */\nfunction storage(): Storage | undefined {\n  try {\n    return typeof localStorage === 'undefined' ? undefined : localStorage\n  } catch {\n    // Access denied (e.g. privacy mode) — the scope still works in memory.\n    return undefined\n  }\n}\n\n/** Parse one stored section; anything malformed resolves to the defaults. */\nfunction parseStored(raw: string | null): unknown {\n  if (raw === null) return undefined\n  try {\n    return JSON.parse(raw) as unknown\n  } catch {\n    return undefined\n  }\n}\n\n/**\n * Create the browser-local scope.\n * @returns a scope whose snapshot is `ready` immediately, backed by\n * localStorage when available and by memory otherwise.\n */\nexport function createLocalSettingsScope(): ConfigForm<NotificationSettings> {\n  const listeners = new Set<() => void>()\n  const notify = (): void => {\n    for (const listener of listeners) listener()\n  }\n\n  let value: NotificationSettings = resolveNotificationSettings(\n    parseStored(storage()?.getItem(LOCAL_STORAGE_KEY) ?? null),\n  )\n  let revision = 1\n\n  const snapshot = (): ConfigFormSnapshot<NotificationSettings> => ({\n    status: 'ready',\n    value,\n    base: DEFAULT_NOTIFICATION_SETTINGS,\n    user: undefined,\n    revision,\n    writable: true,\n  })\n\n  const commit = (next: NotificationSettings, persist: boolean): void => {\n    value = next\n    revision += 1\n    if (persist) {\n      try {\n        storage()?.setItem(LOCAL_STORAGE_KEY, JSON.stringify(next))\n      } catch {\n        // Quota/access errors keep the in-memory value; nothing else to do.\n      }\n    }\n    notify()\n  }\n\n  // Writes from other tabs arrive through the browser storage event, keeping\n  // the \"sync across tabs\" behavior the host-document path used to provide.\n  if (typeof window !== 'undefined') {\n    window.addEventListener('storage', (event) => {\n      if (event.key !== LOCAL_STORAGE_KEY) return\n      commit(resolveNotificationSettings(parseStored(event.newValue)), false)\n    })\n  }\n\n  return {\n    getSnapshot: snapshot,\n    subscribe(listener: () => void): () => void {\n      listeners.add(listener)\n      return () => { listeners.delete(listener) }\n    },\n    // The local scope is its own document: fold every op over the stored\n    // value (deep set/unset), then validate through the same decoder as any\n    // other write so malformed payloads degrade to the defaults.\n    async mutate(ops: readonly SettingsPathOpView[], _expectedRevision?: number): Promise<boolean> {\n      const next = JSON.parse(JSON.stringify(value)) as Record<string, unknown>\n      for (const op of ops) {\n        if (op.path.length === 0) {\n          // The empty path addresses the section root.\n          if (op.op === 'set') {\n            for (const key of Object.keys(next)) delete next[key]\n            Object.assign(next, op.value)\n          }\n          continue\n        }\n        if (op.op === 'set') deepSet(next, op.path, op.value)\n        else deepUnset(next, op.path)\n      }\n      commit(resolveNotificationSettings(next), true)\n      return true\n    },\n    async set(field: string, fieldValue: unknown): Promise<boolean> {\n      commit(resolveNotificationSettings({ ...value, [field]: fieldValue }), true)\n      return true\n    },\n    async unset(field: string): Promise<boolean> {\n      const fallback = (DEFAULT_NOTIFICATION_SETTINGS as unknown as Record<string, unknown>)[field]\n      commit(resolveNotificationSettings({ ...value, [field]: fallback }), true)\n      return true\n    },\n  }\n}\n\n/** Walk one path and assign the value at its end (creating intermediates). */\nfunction deepSet(root: Record<string, unknown>, path: readonly string[], value: unknown): void {\n  let cursor: unknown = root\n  for (let index = 0; index < path.length - 1; index += 1) {\n    const segment = path[index]\n    const next = (cursor as Record<string, unknown>)[segment]\n    if (typeof next !== 'object' || next === null || Array.isArray(next)) {\n      const created: Record<string, unknown> = {}\n      ;(cursor as Record<string, unknown>)[segment] = created\n      cursor = created\n    } else {\n      cursor = next\n    }\n  }\n  ;(cursor as Record<string, unknown>)[path[path.length - 1]] = value\n}\n\n/** Walk one path and delete the value at its end (no-op when absent). */\nfunction deepUnset(root: Record<string, unknown>, path: readonly string[]): void {\n  let cursor: unknown = root\n  for (let index = 0; index < path.length - 1; index += 1) {\n    const next = (cursor as Record<string, unknown>)[path[index]]\n    if (typeof next !== 'object' || next === null || Array.isArray(next)) return\n    cursor = next\n  }\n  delete (cursor as Record<string, unknown>)[path[path.length - 1]]\n}\n"
    },
